alter policy sales_shifts_public_insert on public.sales_shifts with check(public.is_admin() or (public.is_staff() and exists(select 1 from public.staff_accounts a join public.sales_employees e on e.person_id=a.person_id where a.user_id=auth.uid() and a.active and e.id=employee_id)));
alter policy sales_shifts_public_update on public.sales_shifts using(public.is_admin() or exists(select 1 from public.staff_accounts a join public.sales_employees e on e.person_id=a.person_id where a.user_id=auth.uid() and a.active and e.id=employee_id)) with check(public.is_admin() or exists(select 1 from public.staff_accounts a join public.sales_employees e on e.person_id=a.person_id where a.user_id=auth.uid() and a.active and e.id=employee_id));
alter policy sales_shift_employees_public_insert on public.sales_shift_employees with check(public.is_admin() or (public.is_staff() and exists(select 1 from public.staff_accounts a join public.sales_employees e on e.person_id=a.person_id where a.user_id=auth.uid() and a.active and e.id=employee_id)));
alter policy sales_shift_employees_public_update on public.sales_shift_employees using(public.is_admin() or exists(select 1 from public.staff_accounts a join public.sales_employees e on e.person_id=a.person_id where a.user_id=auth.uid() and a.active and e.id=employee_id)) with check(public.is_admin() or exists(select 1 from public.staff_accounts a join public.sales_employees e on e.person_id=a.person_id where a.user_id=auth.uid() and a.active and e.id=employee_id));
